// Primeira porta: so passa adiante uma notificacao de cobranca de verdade.
// O Mercado Pago avisa em dois formatos: o antigo ("payment") e o novo
// ("order"). Os dois chegam aqui; o resto e descartado.
// A protecao que vale dinheiro nao e esta: e a reconsulta na API, no proximo
// no. Esta aqui descarta barulho e, com segredo configurado, confere a
// assinatura.
const req = $input.first().json;
const headers = req.headers ?? {};
const query = req.query ?? {};
const body = req.body ?? {};

const topico = String(
  query.topic || query.type || body.type || body.topic || ''
).toLowerCase();

// merchant_order e outra coisa: o pedido do checkout antigo, sem valor aqui.
if (topico.includes('merchant_order')) return [];

let tipo = null;
if (topico.includes('payment')) tipo = 'payment';
else if (topico.includes('order')) tipo = 'order';
if (!tipo) return [];

const id = String(
  body?.data?.id ?? query['data.id'] ?? query.id ?? body?.id ?? ''
).trim();
if (!id) return [];

let segredo = '';
try { segredo = $env.MP_WEBHOOK_SECRET || ''; } catch (e) { segredo = ''; }

if (segredo) {
  const assinatura = String(headers['x-signature'] ?? '');
  const partes = Object.fromEntries(
    assinatura.split(',').map((p) => p.split('=').map((s) => s.trim())),
  );
  const manifesto =
    'id:' + id +
    ';request-id:' + (headers['x-request-id'] ?? '') +
    ';ts:' + (partes.ts ?? '') + ';';

  let calculada;
  try {
    const chave = await crypto.subtle.importKey(
      'raw',
      new TextEncoder().encode(segredo),
      { name: 'HMAC', hash: 'SHA-256' },
      false,
      ['sign'],
    );
    const buf = await crypto.subtle.sign('HMAC', chave, new TextEncoder().encode(manifesto));
    calculada = [...new Uint8Array(buf)].map((b) => b.toString(16).padStart(2, '0')).join('');
  } catch (erro) {
    throw new Error(
      'Nao consegui calcular a assinatura neste n8n. Remova MP_WEBHOOK_SECRET para seguir sem a conferencia. Detalhe: ' + erro.message,
    );
  }

  if (calculada !== partes.v1) throw new Error('Assinatura do webhook invalida.');
}

return [{
  json: {
    tipo: tipo,
    id: id,
    recurso: tipo === 'payment' ? 'v1/payments/' + id : 'v1/orders/' + id,
    bruto: body,
  },
}];

// O Mercado Pago avisa de varias mudancas de estado. So pagamento concluido
// e dinheiro. Os dois formatos (payment e order) sao normalizados aqui para
// o resto do fluxo nao precisar saber a diferenca.
const dados = $input.first().json;
const origem = $('Validar notificacao').item.json;

let pagamentoId, situacao, valor, referencia, metodoBruto, aprovadoEm, pagador;

if (origem.tipo === 'payment') {
  pagamentoId = String(dados.id ?? origem.id);
  situacao = dados.status;
  valor = dados.transaction_amount;
  referencia = dados.external_reference;
  metodoBruto = dados.payment_type_id;
  aprovadoEm = dados.date_approved;
  pagador = dados.payer;
} else {
  const pagamentos = dados?.transactions?.payments ?? [];
  const pago = pagamentos[0] ?? {};
  pagamentoId = String(pago.id ?? dados.id ?? origem.id);
  situacao = pago.status ?? dados.status;
  valor = pago.amount ?? dados.total_amount;
  referencia = dados.external_reference;
  metodoBruto = pago?.payment_method?.type ?? pago?.payment_method?.id;
  aprovadoEm = pago.date_approved ?? dados.last_updated_date ?? null;
  pagador = dados.payer;
}

// "approved" e o termo do formato antigo, "processed" o do novo.
if (!['approved', 'processed'].includes(String(situacao))) return [];

const metodos = {
  credit_card: 'credit_card',
  debit_card: 'debit_card',
  ticket: 'boleto',
  bank_transfer: 'pix',
  account_money: 'transfer',
  pix: 'pix',
};

// O external_reference foi preenchido pela Leona com o telefone do contato.
const telefone = String(referencia ?? '').replace(/[^0-9]/g, '');
if (!telefone) {
  throw new Error(
    'Cobranca ' + origem.id + ' chegou sem telefone no external_reference. Conteudo recebido: ' +
    JSON.stringify(dados).slice(0, 1500),
  );
}

// O ERP guarda telefone no formato nacional, de 10 ou 11 digitos, e recusa
// o numero com o 55 na frente. A Leona precisa do numero inteiro, entao os
// dois formatos seguem juntos.
let nacional = telefone;
if (nacional.length > 11 && nacional.startsWith('55')) nacional = nacional.slice(2);

const nome =
  dados?.metadata?.nome ||
  [pagador?.first_name, pagador?.last_name].filter(Boolean).join(' ').trim() ||
  'Cliente do WhatsApp';

return [{
  json: {
    paymentId: pagamentoId,
    telefone: telefone,
    telefoneNacional: nacional,
    nome: nome,
    valor: Number(valor).toFixed(2),
    metodo: metodos[metodoBruto] ?? null,
    aprovadoEm: aprovadoEm,
  },
}];

// Aqui mora a garantia de nao mandar a mensagem duas vezes.
// Duas redes, nao uma: o cabecalho Idempotency-Key devolve a resposta guardada
// do primeiro envio, e o indice unico (provedor, id externo) do ERP responde
// 409 se o reenvio vier com outra chave. Qualquer um dos dois significa
// "ja tratamos essa cobranca", e o fluxo para aqui sem avisar a Leona.
const res = $input.first().json;
const status = res.statusCode ?? 0;
const corpo = res.body ?? {};

if (corpo?.meta?.idempotent === true) return [];
if (status === 409) return [];

if (status >= 400) {
  throw new Error('O ERP recusou o lancamento: ' + JSON.stringify(corpo));
}

return [{ json: { transacao: corpo?.data ?? null } }];
